import pandas as pd
from scipy.stats import pearsonr

df = pd.read_csv('3901.csv')
corr_coef, p_value = pearsonr(df['TOTUSJH'], df['TOTUSJZ'])
corr_type = "No Significant Correlation"
if p_value < 0.05:
    if corr_coef > 0:
        corr_type = "Positive Correlation"
    elif corr_coef < 0:
        corr_type = "Negative Correlation"
    else:
        corr_type = "No Correlation"
print(f"@correlation_type[{corr_type}] @correlation_coefficient[{corr_coef:.2f}] @p_value[{p_value:.3f}]")

import pandas as pd

df = pd.read_csv('titanic_test.csv')
result = {}
for sex in ['male', 'female']:
    for pclass in [1, 2, 3]:
        avg_age = df[(df['Sex'] == sex) & (df['Pclass'] == pclass)]['Age'].mean()
        result[f'{sex}_class{pclass}'] = round(avg_age, 2)

print(f"@average_age_male_class2[{result['male_class2']}] @average_age_female_class3[{result['female_class3']}] @average_age_female_class1[{result['female_class1']}] @average_age_female_class2[{result['female_class2']}] @average_age_male_class1[{result['male_class1']}] @average_age_male_class3[{result['male_class3']}]")

